 root.querySelector('[name="clientId"]').onchange=ev=>root.querySelector('[name="vehicleId"]').innerHTML=selectOptions(s.vehicles.filter(v=>v.clientId===ev.target.value),vehicleLabel).map(o=>`<option value="${e(o.value)}">${e(o.label)}</option>`).join('');
 bindForm('edit-form',data=>{const a=saveRescue(data,session.id);notify(`Auxilio ${a.id} registrado.`);go('auxilio');});
 root.insertAdjacentHTML('beforeend',`<section class="panel separated"><h2 class="form-section-title">AUXILIOS REGISTRADOS</h2>${table(['Solicitud','Fecha','Cliente','Vehículo','Ubicación','Técnico'],s.rescues.slice().reverse().map(a=>[e(a.id),date(a.createdAt),e(s.clients.find(c=>c.id===a.clientId)?.name),e(s.vehicles.find(v=>v.id===a.vehicleId)?.plate),e(a.location),e(s.users.find(u=>u.id===a.technicianId)?.name)]))}</section>`);
