function renderTasks({root,session},s){
 const isAux=session.role==='Auxiliar',kevin=isAux?session.id:'u-kevin',name=s.users.find(u=>u.id===kevin)?.name||session.name;
 const orders=s.orders.filter(o=>o.assistantId===kevin&&ACTIVE_STATES.includes(o.state));
 root.innerHTML=pageHeader(`Hola, ${name}`,'Mis tareas · órdenes asignadas',link('Volver a Auxilio mecánico','auxilio'))+`<div class="task-grid">${orders.map(o=>{const c=getContext(s,o);return `<article class="panel task-card"><div class="task-heading"><span class="task-order">${e(o.id)}</span>${badge(o.state)}</div><h2>${e(c.vehicle?.brand)} ${e(c.vehicle?.model)} · ${e(c.vehicle?.plate)}</h2><p>${e(c.quote?.items.filter(i=>i.type==='Servicio').map(i=>i.concept).join(', '))}</p><button type="button" class="primary-button" data-task="${e(o.id)}">Actualizar estado ${icon('arrow')}</button></article>`;}).join('')||'<section class="panel"><p>No hay tareas activas asignadas.</p></section>'}</div>`;
 root.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const o=s.orders.find(o=>o.id===b.dataset.task);const dialog=showModal('Actualizar estado · '+o.id,form('REGISTRAR AVANCE',select('Estado de la orden','state',['Pendiente','En reparación','En pruebas'],o.state,'required')+textarea('Observación / avance','note','','required maxlength="4000"'),submit('Guardar cambios')+button('Cancelar','cancel'),'task-form'));dialog.querySelector('[data-action="cancel"]').onclick=()=>dialog.close();bindForm('task-form',data=>{updateOrder(o.id,{...data,mechanicId:o.mechanicId,assistantId:o.assistantId,result:'No aplica',test:''},session.id);dialog.close();notify('Estado actualizado.');go('auxilio/tareas');});});
}
